import{d as s,C as n,o as g,c as h,E as i,a3 as a}from"./chunks/framework.D4-ViStF.js";const x=JSON.parse('{"title":"遁卦","description":"天山遁，乾 ☰ 艮 ☶","frontmatter":{"title":"遁卦","description":"天山遁，乾 ☰ 艮 ☶","category":"hexagram","aliases":["遁","天山遁"],"source":["《周易》"]},"headers":[],"relativePath":"yijing/hexagrams/hexagram-33.md","filePath":"yijing/hexagrams/hexagram-33.md","lastUpdated":1788516578000}'),p={name:"yijing/hexagrams/hexagram-33.md"},y=s({...p,setup(u){const o=[{id:"dun",term:"遁",pinyin:"dùn",meaning:"退避、隐遁。遁不是逃，是审时度势后的从容撤退。",context:"遁卦之名，六爻皆言「遁」。"},{id:"dunwei",term:"遁尾",pinyin:"dùn wěi",meaning:"遁在末尾、落在最后才退。身处险局而不自知。"},{id:"li",term:"厉"},{id:"wuyongyoyouwang",term:"勿用有攸往",pinyin:"wù yòng yǒu yōu wǎng",meaning:"不要再有所前往。攸，所。",context:"已落在最后，再往前赶只会更险。"},{id:"huangniuzhige",term:"黄牛之革",pinyin:"huáng niú zhī gé",meaning:"黄牛皮制的革绳，坚韧难断。喻坚定而绵韧的系缚。"},{id:"mozhishengtuo",term:"莫之胜说",pinyin:"mò zhī shēng tuō",meaning:"没有办法挣脱。说通「脱」。",context:"象曰点破：不是被捆住，是固志。"},{id:"guzhi",term:"固志",pinyin:"gù zhì",meaning:"坚定其志向。「执用黄牛，固志也」——以不遁为遁，安住本位。"},{id:"xidun",term:"系遁",pinyin:"xì dùn",meaning:"被牵绊、系累的遁。心有牵挂，退不干净。"},{id:"youjibei",term:"有疾惫",pinyin:"yǒu jí bèi",meaning:"有毛病、疲惫困顿。「系遁之厉，有疾惫也」。"},{id:"xuchenqie",term:"畜臣妾",pinyin:"xù chén qiè",meaning:"蓄养臣仆妻妾；引申为安顿好身边人、尽到责任。",context:"畜臣妾吉——牵绊未了时，先安顿再退。"},{id:"haodun",term:"好遁",pinyin:"hào dùn",meaning:"从容、美好的遁。当退则退，不拖泥带水。",context:"好遁不是「喜欢遁」，而是「遁得好」。"},{id:"jiadun",term:"嘉遁",pinyin:"jiā dùn",meaning:"美善的遁。居尊位而能退，光明正大，泽被后世。"},{id:"feidun",term:"肥遁",pinyin:"féi dùn",meaning:"丰盛、宽裕的遁。不是两手空空地逃，是道在身上、满载而归地退。"},{id:"yizhengzhi",term:"以正志",pinyin:"yǐ zhèng zhì",meaning:"以端正其志向。「嘉遁贞吉，以正志也」。"},{id:"wusuoyi",term:"无所疑",pinyin:"wú suǒ yí",meaning:"没有任何疑惑迟疑。「肥遁无不利，无所疑也」。"}],e=[{position:"初六",type:"yin",text:"遁尾，厉，勿用有攸往。",xiang:"遁尾之厉，不往何灾也。",textModern:"撤退落在末尾，危险；不要再有所前往。",xiangModern:"退在末尾的祸患，恰恰在于还要往前赶；不前往，又哪来的灾呢。"},{position:"六二",type:"yin",text:"执之用黄牛之革，莫之胜说。",xiang:"执用黄牛，固志也。",textModern:"被黄牛皮做的革绳捆住，挣脱不掉。",xiangModern:"用黄牛皮绳捆住，是为了坚定它的志向——以不遁为遁。"},{position:"九三",type:"yang",text:"系遁，有疾厉，畜臣妾吉。",xiang:"系遁之厉，有疾惫也。畜臣妾吉，不可大事也。",textModern:"被牵绊着的遁，有毛病、有危险；但安顿好身边人，就吉。",xiangModern:"系遁之所以危险，是因为心有牵挂而疲惫困顿；安顿好身边人则吉，因为此时本就不该图谋大事。"},{position:"九四",type:"yang",text:"好遁，君子吉，小人否。",xiang:"君子好遁，小人否也。",textModern:"从容美好的遁：君子吉，小人做不到。",xiangModern:"君子能遁得好，小人则不能——君子用心，小人只用习惯。"},{position:"九五",type:"yang",text:"嘉遁，贞吉。",xiang:"嘉遁贞吉，以正志也。",textModern:"美善的遁，守正则吉。",xiangModern:"嘉遁之所以贞吉，是因为志向端正——退得光明，泽被后世。"},{position:"上九",type:"yang",text:"肥遁，无不利。",xiang:"肥遁无不利，无所疑也。",textModern:"丰盛宽裕地遁，无所不利。",xiangModern:"肥遁无所不利，是因为心中无疑——道在身上，退到哪里都无碍。"}];return(m,t)=>{const r=n("DaoHexagramViewer"),l=n("DaoHexagramYaoCards"),d=n("DaoKeywordCards");return g(),h("div",null,[i(r,{name:"遁",fullName:"天山遁",upper:"☰",lower:"☶",guaCi:"遁，亨，小利贞。",pinyin:["dùn"],element:"金",direction:"西北",insight:"天下有山，天退而益高；遁不是逃，是审时度势后的从容撤退。",guaSlug:"33tianshandun",lines:e}),t[0]||(t[0]=a('<h2 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to &quot;象传&quot;">​</a></h2><p>天下有山，遁。君子以远小人，不恶而严。</p><p>天下有山：山在下、天在上，山势再高，也在天之下；天不与山争高，反而因退而益显其高——这就是遁。君子由此领悟：远离小人，不露憎恶之态，却自有不容侵犯的威严。</p><p>「不恶而严」——<strong>不恶</strong>是不憎恶、不结怨；<strong>严</strong>是威严、界限。远离不是逃跑，是不给小人伤害你的机会，也不让自己变得像小人一样好斗。恶则结怨，近则受污；不恶而严，是距离的智慧。</p><p>分形结构：</p><ul><li>山（艮）→ 退守：山虽然高，终究退于天之下</li><li>天（乾）→ 高远：天不争山之高，反而因退而成其高</li></ul><p>遁不是消极躲避，是保持高度。天与山的关系说明：真正的远离，不需要吵架，靠的是把自己放得更高。</p><h2 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to &quot;彖传&quot;">​</a></h2><p>遁亨，遁而亨也。刚当位而应，与时行也。小利贞，浸而长也。遁之时义大矣哉。</p><p>逐句释义：</p><ul><li><strong>遁亨，遁而亨也</strong> —— 遁之所以亨通，正因为遁。退一步，海阔天空。</li><li><strong>刚当位而应，与时行也</strong> —— 九五阳刚当位（居中得正），与六二相应；刚者能审时度势，与时进退。</li><li><strong>小利贞，浸而长也</strong> —— 之所以利于小处守正，是因为阴柔（小人之势）正在渐渐滋长，此时不宜大动。</li><li><strong>遁之时义大矣哉</strong> —— 遁在时势中的意义，太重大了。</li></ul><blockquote><p><strong>遁的时义</strong>：遁不是逃避，是与时偕行。懂得遁的人，才懂得什么叫「时」——进退之间，皆有其时。</p></blockquote><h2 id="六爻" tabindex="-1">六爻 <a class="header-anchor" href="#六爻" aria-label="Permalink to &quot;六爻&quot;">​</a></h2>',13)),i(l,{element:"金",guaSlug:"33tianshandun",glossary:o,items:e}),t[1]||(t[1]=a('<h2 id="六爻详解" tabindex="-1">六爻详解 <a class="header-anchor" href="#六爻详解" aria-label="Permalink to &quot;六爻详解&quot;">​</a></h2><h3 id="初六-·-遁尾-厉-勿用有攸往" tabindex="-1">初六 · 遁尾，厉，勿用有攸往 <a class="header-anchor" href="#初六-·-遁尾-厉-勿用有攸往" aria-label="Permalink to &quot;初六 · 遁尾，厉，勿用有攸往&quot;">​</a></h3><ul><li><strong>遁尾</strong> → 撤退落在末尾、最后才退</li><li><strong>厉</strong> → 危险</li><li><strong>勿用有攸往</strong> → 不要再有所前往</li></ul><p>遁卦讲退，初六却是「遁之尾」——所有人都退了，它还落在最后。阴爻居卦最下，是最早入局、最晚离场的位置。身处险局而不自知，这才是「厉」的真正来源。</p><p>象曰「遁尾之厉，不往何灾也」——退在末尾的祸患，恰恰在于你还要往前赶。已经晚了，再追，只会撞进更大的危险。此时正确的选择不是「赶紧跟上」，而是「不往」——停下，先看清自己在哪。</p><blockquote><p>核心洞见：遁尾之厉，不在「尾」，在「不知」。该退不退，才是最危险的自欺。</p></blockquote><h3 id="六二-·-执之用黄牛之革-莫之胜说" tabindex="-1">六二 · 执之用黄牛之革，莫之胜说 <a class="header-anchor" href="#六二-·-执之用黄牛之革-莫之胜说" aria-label="Permalink to &quot;六二 · 执之用黄牛之革，莫之胜说&quot;">​</a></h3><ul><li><strong>执之</strong> → 捆住它</li><li><strong>黄牛之革</strong> → 黄牛皮制成的革绳，坚韧难断</li><li><strong>莫之胜说</strong> → 没有办法挣脱（说通「脱」）</li></ul><p>六二阴爻居中得正，是遁卦中最「安」的一爻。黄牛之革捆住它，挣脱不开——表面上是被束缚，象曰却说得明白：「执用黄牛，固志也」——捆住它的不是别人，是它自己的志。</p><p>六二不遁。它不逃，是因为它看清楚了：此时此位，安住本位就是最好的遁。以不遁为遁——把外部的束缚，内化成自己的坚守；把「被困」，活成「固志」。</p><blockquote><p>以不遁为遁：真正从容的人，不是没有束缚，而是把束缚变成了方向。</p></blockquote><h3 id="九三-·-系遁-有疾厉-畜臣妾吉" tabindex="-1">九三 · 系遁，有疾厉，畜臣妾吉 <a class="header-anchor" href="#九三-·-系遁-有疾厉-畜臣妾吉" aria-label="Permalink to &quot;九三 · 系遁，有疾厉，畜臣妾吉&quot;">​</a></h3><ul><li><strong>系遁</strong> → 被牵绊着的遁</li><li><strong>有疾厉</strong> → 有毛病、有危险</li><li><strong>畜臣妾吉</strong> → 安顿好身边人，则吉</li></ul><p>九三阳居阳位，刚而躁，下比六二，心有所系——放不下人情、放不下责任、放不下未了之事。带着牵挂退，是「系遁」：退也退不干净，留也留不安稳，进退两难，是谓「有疾」。</p><p>但象曰给了解法：「畜臣妾吉，不可大事也。」走之前，先把身后的事安顿妥帖——家人、伙伴、责任，一件件交代清楚。这样的退，才吉；这样的退，才配得上「不可大事」：牵绊未了时，本就不该图谋大事。</p><blockquote><p>核心洞见：被牵绊的遁，先安顿，再上路。君子的退，是带着担当退的。</p></blockquote><h3 id="九四-·-好遁-君子吉-小人否" tabindex="-1">九四 · 好遁，君子吉，小人否 <a class="header-anchor" href="#九四-·-好遁-君子吉-小人否" aria-label="Permalink to &quot;九四 · 好遁，君子吉，小人否&quot;">​</a></h3><ul><li><strong>好遁</strong> → 从容、美好的遁</li><li><strong>君子吉，小人否</strong> → 君子吉，小人做不到</li></ul><p>九四阳爻居阴位，刚而能柔，下应初六却毫不牵累。同样是「遁」，九三被系，九四却「好」——当退则退，当断则断，退得从容、退得漂亮。</p><p>象曰「君子好遁，小人否也」：为什么小人做不到？因为小人的遁是逃——逃得慌不择路；君子的遁是退——退得心中有数。差在用心：用心做决定的人，知道退是选择；被习惯推着走的人，只把退当逃跑。</p><blockquote><p>好遁：不是「喜欢遁」，而是「遁得好」。用心，不用习惯。</p></blockquote><h3 id="九五-·-嘉遁-贞吉" tabindex="-1">九五 · 嘉遁，贞吉 <a class="header-anchor" href="#九五-·-嘉遁-贞吉" aria-label="Permalink to &quot;九五 · 嘉遁，贞吉&quot;">​</a></h3><ul><li><strong>嘉遁</strong> → 美善的遁</li><li><strong>贞吉</strong> → 守正则吉</li></ul><p>九五阳爻居君位，中正，与六二相应，是遁卦的「君」。居尊位而能遁，是最高明的大退——不是丢下责任跑路，而是内心审问之后、光明正大的退。象曰「嘉遁贞吉，以正志也」：志正，则退得嘉美。</p><p>君位之遁，退的不是位置，是锋芒；守的不是权力，是正志。范蠡泛舟五湖，张良辟谷学道，都退在最高处——退，反而成就了他们。</p><blockquote><p>嘉遁之美：退得光明，还泽被后世。内心审问过的退，才是美善之退。</p></blockquote><h3 id="上九-·-肥遁-无不利" tabindex="-1">上九 · 肥遁，无不利 <a class="header-anchor" href="#上九-·-肥遁-无不利" aria-label="Permalink to &quot;上九 · 肥遁，无不利&quot;">​</a></h3><ul><li><strong>肥遁</strong> → 丰盛、宽裕的遁</li><li><strong>无不利</strong> → 无所不利</li></ul><p>上九阳爻居卦之终，超然物外，无应无比，遁得最彻底、最从容。「肥」不是物质丰肥，而是宽裕——遁不是两手空空地逃，而是满载而归地退：道在身上，处处无碍。</p><p>象曰「肥遁无不利，无所疑也」——心中无疑，才能遁得如此宽裕。肥遁者，退到哪里，道就带到哪里；身在江湖，心在道上。</p><blockquote><p>肥遁之境：不是逃开这个世界，而是带着完整的世界退场。道在身上，无往不利。</p></blockquote><h2 id="【原典层】字词释义" tabindex="-1">【原典层】字词释义 <a class="header-anchor" href="#【原典层】字词释义" aria-label="Permalink to &quot;【原典层】字词释义&quot;">​</a></h2>',32)),i(d,{title:"字词释义",items:[{term:"遁",pinyin:["dùn"],meaning:"退避、隐遁。遁不是逃，是审时度势后的从容撤退。"},{term:"遁尾",pinyin:["dùn","wěi"],meaning:"遁在末尾、落在最后才退。身处险局而不自知。"},{term:"黄牛之革",pinyin:["huáng","niú","zhī","gé"],meaning:"黄牛皮制的革绳，坚韧难断。喻坚定而绵韧的系缚。"},{term:"莫之胜说",pinyin:["mò","zhī","shēng","tuō"],meaning:"没有办法挣脱。说通「脱」。"},{term:"系遁",pinyin:["xì","dùn"],meaning:"被牵绊、系累的遁。心有牵挂，退不干净。"},{term:"畜臣妾",pinyin:["xù","chén","qiè"],meaning:"蓄养臣仆妻妾；引申为安顿好身边人、尽到责任。"},{term:"好遁",pinyin:["hào","dùn"],meaning:"从容、美好的遁。当退则退，不拖泥带水。"},{term:"嘉遁",pinyin:["jiā","dùn"],meaning:"美善的遁。居尊位而能退，光明正大，泽被后世。"},{term:"肥遁",pinyin:["féi","dùn"],meaning:"丰盛、宽裕的遁。道在身上，满载而归。"},{term:"固志",pinyin:["gù","zhì"],meaning:"坚定其志向。「执用黄牛，固志也」——以不遁为遁。"},{term:"浸而长",pinyin:["jìn","ér","zhǎng"],meaning:"渐渐滋长。「小利贞，浸而长也」——阴柔渐长，故宜守正。"},{term:"不恶而严",pinyin:["bù","wù","ér","yán"],meaning:"不憎恶、不结怨，却自有威严与界限。远小人的智慧。"},{term:"远小人",pinyin:["yuàn","xiǎo","rén"],meaning:"远离小人。「君子以远小人」——远是保持距离，不是交战。"},{term:"与时行",pinyin:["yǔ","shí","xíng"],meaning:"与时势同行、随势进退。"}]}),t[2]||(t[2]=a('<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一卦在说什么" tabindex="-1">象：这一卦在说什么 <a class="header-anchor" href="#象-这一卦在说什么" aria-label="Permalink to &quot;象：这一卦在说什么&quot;">​</a></h3><p>遁卦讲的是<strong>退避之道</strong>。上乾（天）下艮（山），山在下、天在上，山势再高，天仍在更高的地方——阴柔渐长、小人日盛，君子退让以避之。退不是输，是保存实力、全身而退。</p><p>卦辞「遁，亨，小利贞」点明：退而能亨；但只宜小事守正，不宜大动干戈——因为阴柔之势正在渐长。</p><h3 id="理-为什么这一卦重要" tabindex="-1">理：为什么这一卦重要 <a class="header-anchor" href="#理-为什么这一卦重要" aria-label="Permalink to &quot;理：为什么这一卦重要&quot;">​</a></h3><p>遁不是逃，是审时度势后的从容撤退。真正的强者，不是永远往前冲，而是知道何时该退。</p><p>三个层次：</p><ol><li><strong>时之遁</strong> —— 看清大势，该退就退（初六的教训：退晚了，厉）</li><li><strong>心之遁</strong> —— 退而不乱，退而有志（六二固志、九五正志）</li><li><strong>道之遁</strong> —— 退到哪，道就在哪（上九肥遁）</li></ol><h3 id="用-今天如何应用" tabindex="-1">用：今天如何应用 <a class="header-anchor" href="#用-今天如何应用" aria-label="Permalink to &quot;用：今天如何应用&quot;">​</a></h3><ol><li>判断「该退」的时刻：当对手势不可挡、当关系已成消耗、当位置已不再合道——退，是选择</li><li>退要有志：不是落荒而逃，是带着方向退（六二「固志」、九五「正志」）</li><li>退要干净：能断则断，不拖泥带水（九四「好遁」），但走前先安顿责任（九三「畜臣妾」）</li><li>把道带在身上：真正的安全不来自位置，来自你自己（上九「肥遁」）</li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>遁卦的完整地图：</p><table tabindex="0"><thead><tr><th>爻位</th><th>爻辞要点</th><th>功课</th><th>关键词</th></tr></thead><tbody><tr><td>卦辞</td><td>遁，亨，小利贞</td><td>退而能亨，小处守正</td><td>与时行</td></tr><tr><td>初六</td><td>遁尾，厉，勿用有攸往</td><td>身处险局而不自知，别再追</td><td>遁尾</td></tr><tr><td>六二</td><td>执之用黄牛之革，莫之胜说</td><td>安住本位，内化束缚</td><td>固志</td></tr><tr><td>九三</td><td>系遁，有疾厉，畜臣妾吉</td><td>被牵绊时，先安顿责任</td><td>不可大事</td></tr><tr><td>九四</td><td>好遁，君子吉，小人否</td><td>用心决定，不靠习惯</td><td>从容之遁</td></tr><tr><td>九五</td><td>嘉遁，贞吉</td><td>内心审问，光明正大地退</td><td>以正志</td></tr><tr><td>上九</td><td>肥遁，无不利</td><td>道在身上，无所不利</td><td>肥遁</td></tr></tbody></table><p>核心洞见：</p><ol><li><strong>遁不是逃</strong>——是审时度势后的从容撤退</li><li><strong>遁尾之厉</strong>——退晚了才危险；该退不退，才是最深的自欺</li><li><strong>以不遁为遁</strong>——六二固志，安住本位，把束缚内化成志向</li><li><strong>走前先安顿</strong>——系遁者畜臣妾，有担当的退才吉</li><li><strong>用心不用习惯</strong>——好遁君子吉，小人做不到</li><li><strong>内心审问</strong>——嘉遁正志，退得光明，影响后世</li><li><strong>道在身上</strong>——肥遁无不利，退到哪，道就到哪</li></ol><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><p>遁卦照见的，是历史里那一群「功成身退」的人——以及他们的反面。</p><ul><li><strong>初六 · 遁尾 → 文种</strong>：范蠡劝他「蜚鸟尽，良弓藏；狡兔死，走狗烹」，他不走，最终被勾践赐剑自尽。身处险局而不自知，退晚了，就成了遁尾。</li><li><strong>六二 · 执用黄牛 → 以不遁为遁</strong>：有时「不跑」才是真正的从容——位置不动，心已定。安住本位，把束缚内化成自己的志。</li><li><strong>九三 · 系遁 → 走前先安顿</strong>：牵绊未了时不强行脱身，先把身后之事交代妥当——有担当的退，才退得稳。</li><li><strong>九四 · 好遁 → 张良</strong>：运筹帷幄、功成之后急流勇退，辟谷学道。当退则退，不拖泥带水。</li><li><strong>九五 · 嘉遁 → 范蠡</strong>：泛舟五湖，三聚三散，退得光明正大，还成就了陶朱公的美名——退得美善，泽被后世。</li><li><strong>上九 · 肥遁 → 王翦</strong>：灭楚前向秦始皇广要田宅，「以贪换安」，让君主安心——退得丰盛宽裕，无所不利。</li></ul><p>而文种、胡雪岩，为什么退不掉？因为他们的根，扎在别人身上——扎在君主的信任上、扎在权贵的庇护上。根扎在别人身上的人，无处可退。</p><blockquote><p>君子是动词，是方向，不是身份标签；道，从自己开始。</p></blockquote><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>相关卦象：咸（第三十一卦）、恒（第三十二卦）、大壮（第三十四卦）</li><li>遁与咸的连结：咸是感——情感的感应与牵系；遁是断——情感的抽离与退避。九三「系遁」正是被「感」所系：感应越深，越要知道何时抽身。</li><li>遁与恒的连结：恒是知止——到点收手；遁是知退——避开锋芒、全身而退。能退、能止，恒才有善终。</li><li>遁与大壮的连结：大壮是阳盛而进，遁是阴长而退；一进一退，是时势的两面。大壮「羝羊触藩」进无可进，遁「肥遁」退无所退——盛极而遁，遁而后能再壮。</li><li>相关专题：<a href="/Dao/topics/yin-yang">阴阳</a>、<a href="/Dao/topics/xiang-shu-li">象数理</a></li></ul>',22))])}}});export{x as __pageData,y as default};
